CREATE TABLE [dbo].[RIA_PREGUNTAS](	  [id_pregunta] INT NOT NULL IDENTITY(1,1)	, [id_concepto] INT NOT NULL	, [num_pregunta] INT NOT NULL	, [id_TipoPregunta] INT NOT NULL	, [enunciado_pregunta] VARCHAR(256) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [peso] INT NOT NULL	, [valor_inicial] INT NULL	, [incremento] INT NULL	, CONSTRAINT [PK_RIA_PREGUNTAS] PRIMARY KEY ([id_pregunta] ASC))